128	    10	/** Conexões e transações. Dentro de uma transação, todo acesso na mesma thread usa a mesma conexão. */
129	    11	public final class Database implements AutoCloseable {
130	    12	    private final HikariDataSource dataSource;
131	    13	    private final ThreadLocal<Connection> current = new ThreadLocal<>();
132	    14	
133	    15	    public Database(String url, String user, String password) {
134	    16	        HikariConfig config = new HikariConfig();
135	    17	        config.setJdbcUrl(url);
136	    18	        config.setUsername(user);
137	    19	        config.setPassword(password);
138	    20	        config.setMaximumPoolSize(10);
139	    21	        config.setInitializationFailTimeout(60_000);
140	    22	        this.dataSource = new HikariDataSource(config);
141	    23	    }
142	    24	
143	    25	    public interface SqlWork<T> {
144	    26	        T run(Connection connection) throws SQLException;
145	    27	    }
146	    28	
147	    29	    public <T> T use(SqlWork<T> work) {
148	    30	        Connection existing = current.get();
149	    31	        if (existing != null) {
150	    32	            return run(work, existing);
151	    33	        }
152	    34	        try (Connection connection = dataSource.getConnection()) {
153	    35	            return run(work, connection);
154	    36	        } catch (SQLException e) {
155	    37	            throw new DataAccessException(e);
156	    38	        }
157	    39	    }
158	    40	
159	    41	    public <T> T transaction(Supplier<T> work) {
160	    42	        if (current.get() != null) {
161	    43	            return work.get();
162	    44	        }
163	    45	        try (Connection connection = dataSource.getConnection()) {
164	    46	            connection.setAutoCommit(false);
165	    47	            current.set(connection);
166	    48	            try {
167	    49	                T result = work.get();
168	    50	                connection.commit();
169	    51	                return result;
170	    52	            } catch (Throwable t) {
171	    53	                connection.rollback();
172	    54	                throw t;
173	    55	            } finally {
174	    56	                current.remove();
175	    57	            }
176	    58	        } catch (SQLException e) {
177	    59	            throw new DataAccessException(e);
178	    60	        }
179	    61	    }
180	    62	
181	    63	    private <T> T run(SqlWork<T> work, Connection connection) {
182	    64	        try {
183	    65	            return work.run(connection);
184	    66	        } catch (SQLException e) {
185	    67	            throw new DataAccessException(e);
186	    68	        }
187	    69	    }
188	    70	
189	    71	    @Override
190	    72	    public void close() {
191	    73	        dataSource.close();
192	    74	    }
193	    75	}
