506	    60	    public static void create(Database db) {
507	    61	        db.transaction(() -> db.use(connection -> {
508	    62	            // Evita que duas instâncias subindo juntas criem as tabelas ao mesmo tempo.
509	    63	            try (var lock = connection.createStatement()) {
